import{w as n}from"./CHL1uWRV.js";const s=n("en"),l=[{code:"en",label:"English",native:"English"},{code:"el",label:"Greek",native:"Ελληνικά"},{code:"it",label:"Italian",native:"Italiano"}],a={en:{"nav.home":"Home","nav.lexicon":"Explore the Lexicon","nav.gender":"Gender","nav.keyness":"Italy vs Rhodes","nav.collocations":"Word Pairs","nav.crosslingual":"Across Languages","nav.exhibition":"Slideshow","nav.about":"About","home.title":"Avalanche Lexicon of WWII Memory","home.subtitle":"A bilingual word list from WWII oral testimonies in Greek and Italian.","home.intro":"Built from 397 survivor and witness testimonies across five oral history collections, the lexicon shows how survivors chose their words to remember war.","home.cta":"Explore the Lexicon","home.section1_label":"02 — The Collections","home.section1_title":"Five oral history collections","home.section1_desc":"The lexicon draws on testimonies from five collections in Greece and Italy, each preserving a different side of wartime and post-war memory.","home.section2_label":"01 — The Lexicon","home.section2_title":"Explore the lexicon","home.section2_desc":"Alongside ~400 headwords with concordance lines, collocates, and frequency data, the platform publishes gender keyword lists showing how women and men remember the same events differently, subcorpus comparisons revealing how geography and community shape testimony language, word pairs specific to the wartime context, and 88 Greek–Italian equivalents compared through their collocates to highlight where the two countries’ experiences converge or diverge.","home.btn_lexicon":"Explore the Lexicon","home.btn_gender":"Women vs Men","home.btn_crosslingual":"Across Languages","home.btn_keyness":"Italy vs Rhodes","home.btn_exhibition":"Slideshow","home.btn_gender_desc":"Which words do women use more than men, and vice versa?","home.btn_crosslingual_desc":"88 Greek–Italian word pairs compared through their contexts.","home.btn_keyness_desc":"How does testimony vocabulary differ across archives?","home.btn_exhibition_desc":"Full-screen presentation cycling through headwords and testimony quotes.","home.btn_lexicon_desc":"Browse ~400 headwords with concordance lines, word sketches, and frequency data.","home.testimonies":"testimonies","home.women":"women","home.men":"men","home.women_only":"women only","gender.title":"Gender","gender.intro":"Words that women and men use differently when telling the same stories. Bars show how strongly each word is associated with one group.","gender.underlined_note":"Underlined words are in the lexicon — click to explore. Hover over any row for details.","gender.micro_guide":"Words are ranked by how many times more frequent they are in one group. Longer bar = bigger difference. Click any underlined word for its full profile.","gender.more_in_women":"more in women's","gender.more_in_men":"more in men's","gender.only_women":"only in women's testimonies","gender.only_men":"only in men's testimonies","gender.hl_ravensbruck":"Ravensbrück was the largest Nazi concentration camp primarily for women. It appears exclusively in women's testimonies in this corpus.","gender.hl_gusen":"Gusen was a subcamp of Mauthausen where male prisoners were subjected to forced labor in granite quarries. It appears exclusively in men's testimonies.","gender.hl_miniera":"Forced labor in mines was an experience specific to male deportees. The word does not appear in women's testimonies.","gender.hl_mamma":"Over 4 times more frequent in women's testimonies. Top collocates: papà, sorella, fratello — the mother figure anchors a family lexicon.","gender.hl_mama_gr":`The word for "mum" is over 17 times more frequent per million words in women's testimonies than in men's.`,"gender.hl_thimame":"Women explicitly signal the act of remembering more than twice as often as men — a narrative framing difference, not just a content difference.","gender.show_exploratory":"Also show unconfirmed words","gender.sort_by":"Sort by:","gender.distinctiveness":"How distinctive","gender.freq_ratio":"Times more frequent","gender.stat_strength":"Confidence","gender.women_distinctive":"Women-distinctive","gender.men_distinctive":"Men-distinctive","gender.words":"words","gender.word_present":"word present","gender.word_absent":"word absent","gender.women_testimonies":"Left = women's testimonies","gender.men_testimonies":"Right = men's testimonies","gender.each_square":"Each square is one testimony. Filled = the word appears in it.","gender.col_word":"word","gender.col_testimonies":"testimonies","keyness.title":"Italy vs Rhodes","keyness.intro":"Which words do Italian Jewish survivors use more than the Rhodes community, and vice versa? This page compares how often words appear in each group.","keyness.fold_note":"The ×N value shows how many times more common a word is on one side.","keyness.gender_link":"For gender differences, see the","keyness.gender_page":"Gender page","keyness.micro_guide":"Each word shown is used significantly more by one group. Longer bar = bigger difference.","keyness.metric":"Measure:","keyness.show_top":"Show top","keyness.per_side":"per side","keyness.central_axis":"centre","keyness.sig":"confirmed","keyness.terms":"words","colloc.title":"Word Pairs","colloc.intro":"Words that appear near each other unusually often in testimonies. Browse by archive and word type.","colloc.micro_guide":"Select an archive, then click column headers to sort by MI (most distinctive pairs) or frequency (most common). Search for any word.","colloc.no_data":"No word pairs for this combination.","colloc.legend_mi":"<strong>MI</strong> (Mutual Information) — measures how strongly two words are drawn to each other. Higher MI = the pair appears together far more than you would expect by coincidence.","colloc.legend_freq":"<strong>Freq</strong> — how many times the pair appears together in testimonies.","colloc.legend_tip":"Click column headers to re-sort by MI (most distinctive pairs) or by frequency (most common pairs).","cross.title":"Across Languages","cross.intro":"Greek–Italian word pairs that mean the same thing. Where available, each pair shows which nearby words are shared across both languages and which appear only in one.","cross.micro_guide":"Each card compares a Greek–Italian word pair through their collocates. Green chips = shared across both languages. Blue = only in Greek. Orange = only in Italian. Click a word to open its full lexicon entry.","cross.pairs_with_data":"pairs with data","cross.search_placeholder":"Search word or meaning...","cross.pairs":"pairs","cross.both":"both:","cross.only_greek":"only Greek:","cross.only_italian":"only Italian:","exhibit.occurrences":"times used","exhibit.peaks_decile":"Most common around","exhibit.shared_collocates":"shared collocates","lexicon.label":"Explore the Lexicon","lexicon.title":"Browse the full lexicon","lexicon.desc":"Search and explore all words. Click any card to see testimony excerpts, word patterns, common phrases, and links to the other language.","lexicon.micro_guide":"Click any card to see testimony excerpts (concordances), word sketches (grammatical patterns), similar words, and frequency data. Use the search bar or filter by language.","lexicon.search_placeholder":"Search words...","lexicon.all":"All","lexicon.greek":"Greek","lexicon.italian":"Italian","lexicon.entries":"words","lexicon.loading":"Loading...","lexicon.occurrences":"times used","lexicon.files":"testimonies","lexicon.concordances":"In their words","lexicon.how_used":"How this word is used","lexicon.show_less":"Show less","lexicon.show_all_patterns":"Show all {n} patterns","lexicon.sketch_footer":"Words that appear in similar patterns, ranked by how strongly they go together","lexicon.common_phrases":"Common phrases","lexicon.words_similar":"Words used similarly","lexicon.thes_footer":"Words used in the same way with the same companion words in testimonies.","lexicon.keyness_profile":"Where this word stands out","lexicon.more_frequent":"more frequent","lexicon.less_frequent":"less frequent","lexicon.crosslingual_links":"In the other language","explore.title":"Explore by Theme","explore.intro":"The lexicon is organized into thirteen thematic sections that trace the arc of survivor testimony — from pre-war identity and community through persecution, deportation, and the camps, to resistance, liberation, and the ongoing work of memory.","explore.words":"words","explore.filter_all":"All Languages","explore.filter_greek":"Greek","explore.filter_italian":"Italian","theme.words_in":"Words in this theme","theme.mentions":"mentions","theme.peak":"Peak","word.testimonies":"Testimonies","word.distribution":"Distribution","word.collocations":"Collocations","word.comparisons":"Comparisons","word.frequency":"Frequency","word.archive":"Archive","word.gender":"Gender","word.filter_all":"All","word.showing":"Showing {count} of {total} lines","word.peak_decile":"Peak: Decile {n}","word.no_kwic":"No concordance lines found for this word.","word.colloc_title":"Words that frequently appear together","word.colloc_score":"Association score","word.comp_distinctive":"Distinctive in","word.comp_score":"G² score","comp.title":"Compare Perspectives","comp.intro":"Explore how different groups of survivors used distinctive vocabulary to narrate their experiences.","comp.gender_title":"Female & Male Perspectives","comp.gender_desc":"How women and men remember differently — the distinctive vocabulary that reveals gendered experiences of the Holocaust.","comp.geo_title":"Rhodes & Mainland Italy","comp.geo_desc":"The Jewish community of Rhodes had a unique Ladino-speaking identity. Compare their testimony language with mainland Italian survivors.","comp.female_keywords":"Female-distinctive words","comp.male_keywords":"Male-distinctive words","comp.rhodes_keywords":"Rhodes-distinctive words","comp.italy_keywords":"Italy-distinctive words","comp.g2_score":"G² score","comp.frequency":"Frequency","comp.greek_corpus":"Greek Corpus","comp.italian_corpus":"Italian Corpus","comp.view_word":"View word","corpora.title":"The Corpora","corpora.intro":"The lexicon draws on oral history testimonies from five archives across Greece and Italy, comprising 397 testimonies in two languages.","corpora.testimonies":"testimonies","corpora.tokens":"tokens","corpora.female":"female","corpora.male":"male","corpora.greek_section":"Greek Archives","corpora.italian_section":"Italian Archives","search.title":"Concordance Search","search.intro":"Search for any word across the full corpus. Results show the word in its original testimony context.","search.placeholder":"Type a word (e.g. σπίτι, casa, famiglia)…","search.button":"Search","search.indexed":"indexed terms","search.results":"results","search.no_results":"No concordance lines found for","about.title":"About the Lexicon","about.project_title":"The AVALANCHE Project","about.project_p1":"The AVALANCHE Lexicon is developed as part of Work Package 11 of the AVALANCHE project, funded by the European Union’s CERV Programme on European Remembrance (Grant Agreement 101143807).","about.project_p2":"The project runs from May 2024 to April 2026 and brings together partners across Europe — Mubat (coordinator, Italy), Fondazione CDEC (Italy), Aristotle University of Thessaloniki (Greece), and UVSQ (France) — to develop new approaches to Holocaust education through oral history archives.","about.publishes_title":"What the lexicon publishes","about.publishes_intro":"Alongside the lexicon of approximately 400 headwords, the platform publishes several companion resources:","about.publishes_gender":"<strong>Gender keyword lists</strong> showing which words are distinctively more frequent in women’s or men’s testimonies — revealing differences in how female and male survivors, victims, and witnesses express their memories of the same events.","about.publishes_subcorpus":"<strong>Subcorpus keyword lists</strong> comparing the vocabulary of different communities — for example, Jewish survivors in mainland Italy versus the Jewish community of Rhodes — to surface how geography and community shape the language of testimony.","about.publishes_collocations":"<strong>Word pairs (collocations)</strong> that co-occur in each subcorpus, ranked by how strongly the two words are drawn to each other — pairs like <em>camera + gas</em> or <em>fame + sete</em> (hunger + thirst) that reveal the recurring vocabulary of testimony.","about.publishes_crosslingual":"<strong>Cross-lingual word pairs</strong>: 88 Greek–Italian equivalents compared through their collocates and modifiers, highlighting where the two countries’ experiences converge and where they diverge.","about.methodology_title":"Methodology","about.methodology_note_label":"Note:","about.methodology_note":"This lexicon is an exploratory corpus linguistics tool. It surfaces distributional patterns — how often words appear, where they cluster, and what they co-occur with — as evidence for researchers, exhibition visitors, and educators to interpret. It does not make historical claims.","about.corpus_title":"Corpus","about.corpus_p1":"The lexicon draws on 397 oral history testimonies (~2.73 million words) in two languages: 261 in Greek (~1.92M words) and 136 in Italian (~0.81M words).","about.corpus_greek":"The <strong>Greek corpus</strong> comprises testimonies from three archives: USHMM (53 testimonies, 13 female / 40 male, ~392K words), Memories of the Occupation in Greece — MoG (27 testimonies, all female, ~355K words), and Istorima (181 testimonies, all female, ~1.17M words).","about.corpus_italian":"The <strong>Italian corpus</strong> consists of CDEC testimonies from Italy (101 testimonies, 48 female / 53 male, ~645K words) and Rhodes (35 testimonies, 30 female / 5 male, ~168K words).","about.corpus_asr":"Italian testimonies and the USHMM Greek testimonies were transcribed using Automatic Speech Recognition (Whisper Large v3, run locally). MoG and Istorima have manual transcriptions. Minimum frequency thresholds are applied throughout the pipeline to filter out ASR artifacts.","about.nlp_title":"Natural Language Processing","about.nlp_p1":"Testimonies were processed using spaCy NLP pipelines (<code>el_core_news_lg</code> for Greek, <code>it_core_news_lg</code> for Italian), extracting lemmas and parts of speech according to the Universal Dependencies tagset. Only content words (nouns, verbs, adjectives, adverbs, proper nouns) are retained for analysis; function words (determiners, pronouns, prepositions, conjunctions, particles) and numbers are excluded. Greek lemmas undergo accent normalization to merge diacritical variants.","about.plain_terms":"In plain terms:","about.nlp_plain":"The pipeline attempts to reduce each word to its dictionary form (e.g. <em>andavamo</em> → <em>andare</em>, <em>ερχόταν</em> → <em>έρχομαι</em>) and tag it with its grammatical role. Italian lemmatization is generally reliable, but Greek lemmatization is less accurate — some inflected forms may appear as separate entries.","about.headword_title":"Headword Selection","about.headword_p1":"The lexicon contains approximately 400 headwords selected through a multi-step process. All content words meeting minimum frequency (at least 30 total occurrences) and dispersion thresholds (appearing in at least 3 testimonies) are tested for statistical distinctiveness. Words that are distinctive in at least one subcorpus comparison are retained, and a manual curation step removes leaked stopwords and discourse markers. Additionally, some words that do not pass these thresholds are manually included when they are judged to be of interest — since keyword analysis by design surfaces <em>differences</em> between groups, not commonalities, and some historically important words may be shared across all subcorpora.","about.headword_plain":"Most headwords are words that are both frequent enough to be reliable and used notably more by one group of survivors than another. A smaller number are manually added because they carry historical weight even if shared across all groups.","about.frequency_title":"Frequency & Dispersion","about.frequency_p1":"For each headword we compute raw frequency, range (number of testimonies it appears in), frequency per million words, and Gries’ Deviation of Proportions (DP; Gries 2008). DP measures how evenly a word is spread across testimonies on a 0–1 scale: a DP of 0 means the word is used evenly across all testimonies, while a DP close to 1 means it clusters in just a few.","about.frequency_plain":"A word like <em>guerra</em> (war) that appears across nearly all Italian testimonies has low DP (well-dispersed), while a word like <em>cantoni</em> that appears mostly in Rhodes testimonies has high DP (concentrated).","about.keyword_title":"Keyword Analysis","about.keyword_p1":"Keywords are words that are used significantly more by one group of survivors than another. On the site, words are ranked by <strong>frequency ratio</strong> (×N) — how many times more frequent a word is in one group compared to the other. For example, ×4.1 means about four times more frequent.","about.keyword_p2":"Only words that pass a statistical significance test are shown, ensuring the differences are likely real and not due to chance. A minimum frequency of 10 on each side and appearance in at least 3 testimonies are required to prevent single-testimony spikes.","about.keyword_p3":"Comparisons are conducted within the same archive to avoid confounding variables: Italian CDEC female vs. male, Greek USHMM female vs. male, and Italian CDEC Italy vs. Rhodes.","about.keyword_plain":"For example, if <em>mamma</em> (mum) appears about four times more often in Italian women’s testimonies than in men’s, the site shows it as ×4.1.","about.gender_analysis_title":"Gender Analysis","about.gender_analysis_p1":"The gender comparison page shows words ranked by frequency ratio (×N) — how many times more frequent a word is in women’s vs. men’s testimonies (or vice versa). Behind the scenes, words are pre-filtered using two additional tests that must agree on direction:","about.gender_analysis_zeta":"<strong>Burrows’ Zeta</strong> (Burrows 2007; Schöch 2018) — a document-level measure that checks <em>in how many testimonies</em> a word appears on each side, preventing a single long testimony from driving a result.","about.gender_analysis_g2":"A <strong>statistical significance test</strong> to ensure the difference is not due to chance. Only confirmed words are shown.","about.gender_analysis_plain":"A word only makes the list if it is both more frequent and more widespread across testimonies on one side.","about.collocation_title":"Collocation Analysis","about.collocation_p1":"Collocations are word pairs that appear near each other far more often than chance would predict. On the site, pairs are ranked by <strong>Mutual Information</strong> (MI; Church &amp; Hanks 1990), which measures how strongly two words are drawn to each other. High-MI pairs like <em>camera + gas</em>, <em>stella + davide</em>, or <em>fame + sete</em> (hunger + thirst) surface the distinctive vocabulary of testimony.","about.collocation_p2":"The table also shows raw co-occurrence frequency. Collocations are computed within a ±5 word window, with a minimum of 3 co-occurrences in at least 3 different testimonies.","about.collocation_plain":"","about.sketch_title":"Word Sketches & Multi-Word Expressions","about.sketch_p1":"Word sketches (Kilgarriff et al. 2004, 2014) extend collocation analysis by grouping co-occurrences according to grammatical relations extracted from dependency parses. For example, for a noun we can see <em>what verbs take it as subject</em> (what does this thing do?), <em>what adjectives modify it</em> (how is it described?), and <em>what other nouns appear alongside it</em> (what is it connected to?). Association strength is measured with logDice.","about.sketch_p2":"Multi-word expressions (MWEs) are extracted by two methods: dependency-based (compound and fixed relations in the parse tree) and PMI-filtered bigrams/trigrams (Church & Hanks 1990, PMI ≥ 5.0). This captures fixed phrases like <em>campo di concentramento</em>, <em>croce rossa</em>, <em>carta d’identità</em>.","about.thesaurus_title":"Distributional Thesaurus","about.thesaurus_p1":"The distributional thesaurus ranks headwords by how similarly they are used in context, following the Sketch Engine approach (Kilgarriff et al. 2004; Rychlý & Kilgarriff 2007). Each headword is represented as a vector of (grammatical_relation, collocate) pairs weighted by logDice. Similarity is computed as cosine similarity between these vectors.","about.thesaurus_plain":"Two words are considered similar if they appear in the same kinds of sentences with the same kinds of neighboring words. Unlike neural embeddings, every similarity score can be traced back to specific shared collocates — you can see why the system considers two words related.","about.emotion_title":"Emotion Profiles","about.emotion_p1":"Each headword receives an emotion profile derived from its usage contexts using the NRC Emotion Lexicon (Mohammad & Turney 2013), which associates words with eight basic emotions (anger, anticipation, disgust, fear, joy, sadness, surprise, trust) and two sentiment polarities. For each headword, we collect all surrounding context words from concordance lines and look up their emotion associations, producing a distribution across emotion categories.","about.emotion_plain":"This tells us which emotions surround a word when survivors use it. The NRC lexicon is the same across Greek and Italian, which means emotion profiles are directly comparable between languages.","about.narrative_title":"Narrative Position","about.narrative_p1":"Each testimony is divided into 10 equal-length segments (deciles) by token position. For each headword, we count occurrences per decile and test the distribution against the null hypothesis of uniform usage using the chi-squared goodness-of-fit test.","about.narrative_plain":"This reveals <em>when</em> in the testimony arc survivors use specific words. Words like <em>scuola</em> (school) and <em>nonno</em> (grandfather) peak in the first decile — survivors start by setting the scene of their pre-war life. Words like <em>guerra</em> (war) and <em>tedesco</em> (German) peak in the second and third deciles, where the narrative shifts to occupation and persecution.","about.crosslingual_title":"Cross-Lingual Comparison","about.crosslingual_p1":"Greek-Italian word pairs are curated from bilingual dictionaries and domain expertise. For each pair, word sketches from both languages are compared: shared collocates (words used similarly in both languages) are identified using cross-lingual embeddings, while unique collocates reveal language-specific associations.","about.crosslingual_plain":"For the pair <em>πόλεμος</em> (war, Greek) ↔ <em>guerra</em> (war, Italian), we can compare which words surround “war” in each language — revealing whether the two communities frame the same concept through similar or different vocabulary.","about.gender_dim_title":"Gender Dimension","about.gender_dim_p1":"A central aim of this lexicon is to examine how female and male survivors narrate the same experiences through different vocabulary. The Italian CDEC corpus provides the cleanest gender comparison, with roughly balanced female (48) and male (53) testimonies from the same archive. The Greek USHMM comparison (13F vs 40M) is the most controlled Greek gender analysis, but the smaller female sample means results should be interpreted with caution.","about.gender_dim_p2":"Gender statistics combine document-level measures (checking how many testimonies use a word, not just how often) with frequency-based measures, to avoid inflating results from a few long testimonies.","about.limitations_title":"Limitations","about.limit_asr":"<strong>ASR transcription quality:</strong> Italian and Greek USHMM testimonies were transcribed automatically. Minimum frequency and range thresholds filter most artifacts, but some noise remains.","about.limit_greek":"<strong>Greek lemmatization:</strong> Automatic lemmatization for Greek is less accurate than for Italian, especially for verb forms in oral speech. Some inflected forms may appear as separate entries rather than being grouped under one headword.","about.limit_small":"","about.limit_imbalance":"","about.references_title":"References","about.credits_title":"Credits","about.credits_p1":"","about.credits_p2":"Testimonies are provided by CDEC (Centro di Documentazione Ebraica Contemporanea, Milan), the United States Holocaust Memorial Museum (USHMM), the Memories of the Occupation in Greece project (MoG), and the Istorima oral history project.","common.loading":"Loading…","common.language":"Language","common.greek":"Greek","common.italian":"Italian","common.female":"Female","common.male":"Male","common.decile_labels":["Pre-war","Early war","Persecution","Deportation","Camps","Daily life","Liberation","Aftermath","Reflection","Legacy"],"footer.cofunded":"Co-funded by the European Union","footer.partners":"Mubat (coordinator) · Fondazione CDEC · Aristotle University of Thessaloniki · UVSQ","footer.disclaimer":"Funded by the European Union. Views and opinions expressed are however those of the author(s) only and do not necessarily reflect those of the European Union or the European Education and Culture Executive Agency (EACEA). Neither the European Union nor the granting authority can be held responsible for them.","footer.ai_translation":"The Greek and Italian versions of this website were translated with the assistance of AI. Some inaccuracies may exist."},el:{"nav.home":"Αρχική","nav.lexicon":"Εξερεύνηση Λεξικού","nav.gender":"Φύλο","nav.keyness":"Ιταλία vs Ρόδος","nav.collocations":"Ζεύγη Λέξεων","nav.crosslingual":"Ανά Γλώσσα","nav.exhibition":"Παρουσίαση","nav.about":"Σχετικά","home.title":"Avalanche Lexicon of WWII Memory","home.subtitle":"Δίγλωσσος κατάλογος λέξεων από προφορικές μαρτυρίες του Β' Παγκοσμίου Πολέμου στα ελληνικά και ιταλικά.","home.intro":"Βασισμένο σε 397 μαρτυρίες επιζώντων από πέντε συλλογές προφορικής ιστορίας, το λεξικό δείχνει πώς οι επιζώντες επέλεξαν τις λέξεις τους για να θυμηθούν τον πόλεμο.","home.cta":"Εξερεύνηση Λεξικού","home.section1_label":"02 — Οι Συλλογές","home.section1_title":"Πέντε συλλογές προφορικής ιστορίας","home.section1_desc":"Το λεξικό αντλεί από μαρτυρίες πέντε συλλογών προφορικής ιστορίας σε Ελλάδα και Ιταλία, καθεμία διαφυλάσσοντας μια διαφορετική πτυχή της πολεμικής και μεταπολεμικής μνήμης.","home.section2_label":"01 — Το Λεξικό","home.section2_title":"Εξερευνήστε το λεξικό","home.section2_desc":"Μαζί με ~400 λήμματα με γραμμές συμφραζομένων, συνάψεις και δεδομένα συχνότητας, η πλατφόρμα δημοσιεύει λίστες λέξεων-κλειδιών ανά φύλο που δείχνουν πώς γυναίκες και άνδρες θυμούνται διαφορετικά τα ίδια γεγονότα, συγκρίσεις υποσωμάτων που αποκαλύπτουν πώς η γεωγραφία και η κοινότητα διαμορφώνουν τη γλώσσα της μαρτυρίας, ζεύγη λέξεων ειδικά του πολεμικού πλαισίου, και 88 ελληνο-ιταλικά αντίστοιχα που συγκρίνονται μέσω των συνάψεών τους.","home.btn_lexicon":"Εξερεύνηση Λεξικού","home.btn_gender":"Γυναίκες vs Άνδρες","home.btn_crosslingual":"Ανά Γλώσσα","home.btn_keyness":"Ιταλία vs Ρόδος","home.btn_exhibition":"Παρουσίαση","home.btn_gender_desc":"Ποιες λέξεις χρησιμοποιούν περισσότερο οι γυναίκες σε σχέση με τους άνδρες, και αντίστροφα;","home.btn_crosslingual_desc":"88 ελληνο-ιταλικά ζεύγη λέξεων σε σύγκριση μέσα από τα συμφραζόμενά τους.","home.btn_keyness_desc":"Πώς διαφέρει το λεξιλόγιο μαρτυριών μεταξύ αρχείων;","home.btn_exhibition_desc":"Παρουσίαση πλήρους οθόνης με λήμματα και αποσπάσματα μαρτυριών.","home.btn_lexicon_desc":"Περιηγηθείτε σε ~400 λήμματα με αποσπάσματα μαρτυριών, μοτίβα λέξεων και δεδομένα συχνότητας.","home.testimonies":"μαρτυρίες","home.women":"γυναίκες","home.men":"άνδρες","home.women_only":"μόνο γυναίκες","gender.title":"Φύλο","gender.intro":"Λέξεις που γυναίκες και άνδρες χρησιμοποιούν διαφορετικά στις ίδιες ιστορίες. Οι μπάρες δείχνουν πόσο ισχυρά κάθε λέξη συνδέεται με μία ομάδα.","gender.underlined_note":"Οι υπογραμμισμένες λέξεις ανήκουν στο λεξικό — κάντε κλικ για εξερεύνηση. Περάστε τον κέρσορα για λεπτομέρειες.","gender.micro_guide":"Οι λέξεις ταξινομούνται κατά πόσες φορές πιο συχνές είναι σε μία ομάδα. Μεγαλύτερη μπάρα = μεγαλύτερη διαφορά. Κάντε κλικ σε υπογραμμισμένη λέξη για πλήρες προφίλ.","gender.more_in_women":"πιο συχνή στις γυναίκες","gender.more_in_men":"πιο συχνή στους άνδρες","gender.only_women":"μόνο σε μαρτυρίες γυναικών","gender.only_men":"μόνο σε μαρτυρίες ανδρών","gender.hl_ravensbruck":"Το Ravensbrück ήταν το μεγαλύτερο ναζιστικό στρατόπεδο κυρίως για γυναίκες. Εμφανίζεται αποκλειστικά σε μαρτυρίες γυναικών σε αυτό το σώμα κειμένων.","gender.hl_gusen":"Το Gusen ήταν υποστρατόπεδο του Mauthausen όπου άνδρες κρατούμενοι υποβάλλονταν σε καταναγκαστικά έργα. Εμφανίζεται αποκλειστικά σε μαρτυρίες ανδρών.","gender.hl_miniera":"Η καταναγκαστική εργασία σε ορυχεία ήταν εμπειρία συγκεκριμένη των ανδρών κρατουμένων. Η λέξη δεν εμφανίζεται σε μαρτυρίες γυναικών.","gender.hl_mamma":"Πάνω από 4 φορές πιο συχνή στις μαρτυρίες γυναικών. Κύριες συνάψεις: papà, sorella, fratello — η μητέρα αποτελεί τον πυρήνα ενός οικογενειακού λεξιλογίου.","gender.hl_mama_gr":"Η λέξη «μαμά» είναι πάνω από 17 φορές πιο συχνή ανά εκατομμύριο λέξεις στις μαρτυρίες γυναικών σε σχέση με των ανδρών.","gender.hl_thimame":"Οι γυναίκες σηματοδοτούν ρητά την πράξη της ανάμνησης πάνω από δύο φορές πιο συχνά — μια διαφορά αφηγηματικής πλαισίωσης, όχι μόνο περιεχομένου.","gender.show_exploratory":"Εμφάνιση μη επιβεβαιωμένων λέξεων","gender.sort_by":"Ταξινόμηση:","gender.distinctiveness":"Πόσο χαρακτηριστική","gender.freq_ratio":"Πόσο πιο συχνή","gender.stat_strength":"Βεβαιότητα","gender.women_distinctive":"Χαρακτηριστικές γυναικών","gender.men_distinctive":"Χαρακτηριστικές ανδρών","gender.words":"λέξεις","gender.word_present":"λέξη παρούσα","gender.word_absent":"λέξη απούσα","gender.women_testimonies":"Αριστερά = μαρτυρίες γυναικών","gender.men_testimonies":"Δεξιά = μαρτυρίες ανδρών","gender.each_square":"Κάθε τετράγωνο είναι μία μαρτυρία. Γεμάτο = η λέξη εμφανίζεται.","gender.col_word":"λέξη","gender.col_testimonies":"μαρτυρίες","keyness.title":"Ιταλία vs Ρόδος","keyness.intro":"Ποιες λέξεις χρησιμοποιούν πιο πολύ οι Ιταλοί Εβραίοι επιζώντες σε σχέση με την κοινότητα της Ρόδου, και αντίστροφα;","keyness.fold_note":"Η τιμή ×N δείχνει πόσες φορές πιο συχνή είναι μια λέξη στη μία πλευρά.","keyness.gender_link":"Για συγκρίσεις φύλων, δείτε τη σελίδα","keyness.gender_page":"Φύλο","keyness.micro_guide":"Κάθε λέξη που εμφανίζεται χρησιμοποιείται σημαντικά περισσότερο από τη μία ομάδα. Μεγαλύτερη μπάρα = μεγαλύτερη διαφορά.","keyness.metric":"Μέτρο:","keyness.show_top":"Εμφάνιση","keyness.per_side":"ανά πλευρά","keyness.central_axis":"κέντρο","keyness.sig":"βέβαιες","keyness.terms":"λέξεις","colloc.title":"Ζεύγη Λέξεων","colloc.intro":"Λέξεις που εμφανίζονται μαζί ασυνήθιστα συχνά στις μαρτυρίες. Περιηγηθείτε κατά αρχείο και τύπο λέξεων.","colloc.micro_guide":"Επιλέξτε αρχείο, κάντε κλικ στις κεφαλίδες στηλών για ταξινόμηση κατά MI (πιο χαρακτηριστικά ζεύγη) ή συχνότητα (πιο κοινά). Αναζητήστε οποιαδήποτε λέξη.","colloc.no_data":"Δεν υπάρχουν ζεύγη λέξεων για αυτόν τον συνδυασμό.","colloc.legend_mi":"<strong>MI</strong> (Αμοιβαία Πληροφορία) — μετρά πόσο ισχυρά δύο λέξεις «έλκονται» μεταξύ τους. Υψηλότερο MI = το ζεύγος εμφανίζεται μαζί πολύ πιο συχνά απ' ό,τι θα περιμέναμε τυχαία.","colloc.legend_freq":"<strong>Συχν.</strong> — πόσες φορές εμφανίζεται μαζί το ζεύγος στις μαρτυρίες.","colloc.legend_tip":"Κάντε κλικ στις κεφαλίδες στηλών για αναταξινόμηση κατά MI (πιο χαρακτηριστικά ζεύγη) ή κατά συχνότητα (πιο κοινά ζεύγη).","cross.title":"Ανά Γλώσσα","cross.intro":"Ελληνο-ιταλικά ζεύγη λέξεων που σημαίνουν το ίδιο. Όπου υπάρχουν δεδομένα, κάθε ζεύγος δείχνει ποιες λέξεις χρησιμοποιούνται παρόμοια και στις δύο γλώσσες και ποιες μόνο σε μία.","cross.micro_guide":"Κάθε κάρτα συγκρίνει ένα ελληνο-ιταλικό ζεύγος μέσω των συμφραζομένων τους. Πράσινα = κοινά και στις δύο γλώσσες. Μπλε = μόνο ελληνικά. Πορτοκαλί = μόνο ιταλικά. Κάντε κλικ σε λέξη για το πλήρες λήμμα.","cross.pairs_with_data":"ζεύγη με δεδομένα","cross.search_placeholder":"Αναζήτηση λέξης ή σημασίας...","cross.pairs":"ζεύγη","cross.both":"κοινά:","cross.only_greek":"μόνο ελληνικά:","cross.only_italian":"μόνο ιταλικά:","lexicon.label":"Εξερεύνηση Λεξικού","lexicon.title":"Περιήγηση στο λεξικό","lexicon.desc":"Αναζητήστε και εξερευνήστε όλες τις λέξεις. Κάντε κλικ σε κάθε κάρτα για αποσπάσματα μαρτυριών, μοτίβα λέξεων, κοινές φράσεις και συνδέσεις με την άλλη γλώσσα.","lexicon.micro_guide":"Κάντε κλικ σε κάρτα για αποσπάσματα μαρτυριών (συμφραζόμενα), μοτίβα χρήσης (word sketches), παρόμοιες λέξεις και δεδομένα συχνότητας. Χρησιμοποιήστε την αναζήτηση ή φιλτράρετε κατά γλώσσα.","lexicon.search_placeholder":"Αναζήτηση λέξεων...","lexicon.all":"Όλα","lexicon.greek":"Ελληνικά","lexicon.italian":"Ιταλικά","lexicon.entries":"λέξεις","lexicon.loading":"Φόρτωση...","lexicon.occurrences":"φορές","lexicon.files":"μαρτυρίες","lexicon.concordances":"Με τα λόγια τους","lexicon.how_used":"Πώς χρησιμοποιείται αυτή η λέξη","lexicon.show_less":"Λιγότερα","lexicon.show_all_patterns":"Εμφάνιση όλων ({n})","lexicon.sketch_footer":"Λέξεις που εμφανίζονται στα ίδια μοτίβα, ταξινομημένες κατά το πόσο συχνά πάνε μαζί","lexicon.common_phrases":"Κοινές φράσεις","lexicon.words_similar":"Λέξεις με παρόμοια χρήση","lexicon.thes_footer":"Λέξεις που χρησιμοποιούνται με τον ίδιο τρόπο με τις ίδιες συνοδευτικές λέξεις στις μαρτυρίες.","lexicon.keyness_profile":"Πού ξεχωρίζει αυτή η λέξη","lexicon.more_frequent":"πιο συχνή","lexicon.less_frequent":"λιγότερο συχνή","lexicon.crosslingual_links":"Στην άλλη γλώσσα","exhibit.occurrences":"φορές","exhibit.peaks_decile":"Πιο συχνή γύρω στο","exhibit.shared_collocates":"κοινές συνάψεις","explore.title":"Εξερεύνηση ανά Θέμα","explore.intro":"Το λεξικό οργανώνεται σε δεκατρείς θεματικές ενότητες που ακολουθούν την πορεία της μαρτυρίας — από την προπολεμική ταυτότητα και κοινότητα μέσα από τη δίωξη, την εκτόπιση και τα στρατόπεδα, ώς την αντίσταση, την απελευθέρωση και τη συνεχιζόμενη εργασία της μνήμης.","explore.words":"λέξεις","explore.filter_all":"Όλες οι Γλώσσες","explore.filter_greek":"Ελληνικά","explore.filter_italian":"Ιταλικά","theme.words_in":"Λέξεις σε αυτό το θέμα","theme.mentions":"αναφορές","theme.peak":"Κορύφωση","word.testimonies":"Μαρτυρίες","word.distribution":"Κατανομή","word.collocations":"Συνάψεις","word.comparisons":"Συγκρίσεις","word.frequency":"Συχνότητα","word.archive":"Αρχείο","word.gender":"Φύλο","word.filter_all":"Όλα","word.showing":"Εμφάνιση {count} από {total} γραμμές","word.no_kwic":"Δεν βρέθηκαν γραμμές συμφραζομένων για αυτήν τη λέξη.","word.colloc_title":"Λέξεις που εμφανίζονται συχνά μαζί","word.comp_distinctive":"Διακριτική σε","comp.title":"Σύγκριση Οπτικών","comp.intro":"Εξερευνήστε πώς διαφορετικές ομάδες επιζώντων χρησιμοποίησαν χαρακτηριστικό λεξιλόγιο για να αφηγηθούν τις εμπειρίες τους.","comp.gender_title":"Γυναικείες & Ανδρικές Οπτικές","comp.gender_desc":"Πώς γυναίκες και άνδρες θυμούνται διαφορετικά — το χαρακτηριστικό λεξιλόγιο που αποκαλύπτει τις έμφυλες εμπειρίες του Ολοκαυτώματος.","comp.geo_title":"Ρόδος & Ηπειρωτική Ιταλία","comp.geo_desc":"Η εβραϊκή κοινότητα της Ρόδου είχε μοναδική λαδινόφωνη ταυτότητα. Συγκρίνετε τη γλώσσα μαρτυρίας τους με τους ηπειρωτικούς Ιταλούς επιζώντες.","comp.female_keywords":"Γυναικείες λέξεις-κλειδιά","comp.male_keywords":"Ανδρικές λέξεις-κλειδιά","comp.rhodes_keywords":"Λέξεις-κλειδιά Ρόδου","comp.italy_keywords":"Λέξεις-κλειδιά Ιταλίας","corpora.title":"Τα Σώματα Κειμένων","corpora.intro":"Το λεξικό αντλεί από μαρτυρίες προφορικής ιστορίας πέντε αρχείων σε Ελλάδα και Ιταλία, που περιλαμβάνουν 397 μαρτυρίες σε δύο γλώσσες.","corpora.testimonies":"μαρτυρίες","corpora.tokens":"λέξεις","corpora.female":"γυναίκες","corpora.male":"άνδρες","corpora.greek_section":"Ελληνικά Αρχεία","corpora.italian_section":"Ιταλικά Αρχεία","search.title":"Αναζήτηση Συμφραζομένων","search.intro":"Αναζητήστε οποιαδήποτε λέξη στο πλήρες σώμα κειμένων. Τα αποτελέσματα δείχνουν τη λέξη στο αυθεντικό πλαίσιο μαρτυρίας.","search.placeholder":"Πληκτρολογήστε μια λέξη (π.χ. σπίτι, οικογένεια)…","search.button":"Αναζήτηση","search.indexed":"ευρετηριασμένοι όροι","search.no_results":"Δεν βρέθηκαν αποτελέσματα για","about.title":"Σχετικά με το Λεξικό","about.project_title":"Το έργο AVALANCHE","about.project_p1":"Το Λεξικό AVALANCHE αναπτύσσεται στο πλαίσιο του Πακέτου Εργασίας 11 του έργου AVALANCHE, χρηματοδοτούμενο από το πρόγραμμα CERV της Ευρωπαϊκής Ένωσης για την Ευρωπαϊκή Μνήμη (Grant Agreement 101143807).","about.project_p2":"Το έργο διαρκεί από τον Μάιο 2024 έως τον Απρίλιο 2026 και συνενώνει εταίρους από όλη την Ευρώπη — Mubat (συντονιστής, Ιταλία), Fondazione CDEC (Ιταλία), Αριστοτέλειο Πανεπιστήμιο Θεσσαλονίκης (Ελλάδα) και UVSQ (Γαλλία) — για την ανάπτυξη νέων προσεγγίσεων στην εκπαίδευση για το Ολοκαύτωμα μέσω αρχείων προφορικής ιστορίας.","about.publishes_title":"Τι δημοσιεύει το λεξικό","about.publishes_intro":"Παράλληλα με το λεξικό περίπου 400 λημμάτων, η πλατφόρμα δημοσιεύει συμπληρωματικούς πόρους:","about.publishes_gender":"<strong>Λίστες λέξεων-κλειδιών κατά φύλο</strong> που δείχνουν ποιες λέξεις είναι χαρακτηριστικά πιο συχνές στις μαρτυρίες γυναικών ή ανδρών — αποκαλύπτοντας διαφορές στον τρόπο που επιζώντες, θύματα και μάρτυρες εκφράζουν τις μνήμες τους.","about.publishes_subcorpus":"<strong>Λίστες λέξεων-κλειδιών κατά υποσώμα</strong> που συγκρίνουν το λεξιλόγιο διαφορετικών κοινοτήτων — για παράδειγμα, Εβραίοι επιζώντες στην ηπειρωτική Ιταλία σε σύγκριση με την εβραϊκή κοινότητα της Ρόδου — αναδεικνύοντας πώς η γεωγραφία και η κοινότητα διαμορφώνουν τη γλώσσα της μαρτυρίας.","about.publishes_collocations":"<strong>Ζεύγη λέξεων (συνταγματικές συνάψεις)</strong> που συνεμφανίζονται σε κάθε υποσώμα, καταταγμένα ανάλογα με το πόσο ισχυρά «έλκονται» μεταξύ τους — ζεύγη όπως <em>camera + gas</em> ή <em>fame + sete</em> (πείνα + δίψα) που αναδεικνύουν το επαναλαμβανόμενο λεξιλόγιο των μαρτυριών.","about.publishes_crosslingual":"<strong>Διαγλωσσικά ζεύγη λέξεων</strong>: 88 ελληνο-ιταλικά ισοδύναμα που συγκρίνονται μέσω των συνταγματικών τους συνάψεων, αναδεικνύοντας πού οι εμπειρίες των δύο χωρών συγκλίνουν και πού αποκλίνουν.","about.methodology_title":"Μεθοδολογία","about.methodology_note_label":"Σημείωση:","about.methodology_note":"Αυτό το λεξικό είναι ένα διερευνητικό εργαλείο γλωσσολογίας σωμάτων κειμένων. Αναδεικνύει κατανομητικά μοτίβα — πόσο συχνά εμφανίζονται οι λέξεις, πού συγκεντρώνονται και με τι συνεμφανίζονται — ως τεκμήρια προς ερμηνεία από ερευνητές, επισκέπτες εκθέσεων και εκπαιδευτικούς. Δεν διατυπώνει ιστορικούς ισχυρισμούς.","about.corpus_title":"Σώμα κειμένων","about.corpus_p1":"Το λεξικό αντλεί από 397 προφορικές μαρτυρίες (~2,73 εκατ. λέξεις) σε δύο γλώσσες: 261 στα ελληνικά (~1,92 εκατ.) και 136 στα ιταλικά (~0,81 εκατ.).","about.corpus_greek":"Το <strong>ελληνικό σώμα</strong> περιλαμβάνει μαρτυρίες από τρία αρχεία: USHMM (53 μαρτυρίες, 13 γυναίκες / 40 άνδρες, ~392K λέξεις), Μνήμες της Κατοχής στην Ελλάδα — MoG (27 μαρτυρίες, όλες γυναίκες, ~355K λέξεις), και Istorima (181 μαρτυρίες, όλες γυναίκες, ~1,17 εκατ. λέξεις).","about.corpus_italian":"Το <strong>ιταλικό σώμα</strong> αποτελείται από μαρτυρίες CDEC από την Ιταλία (101 μαρτυρίες, 48 γυναίκες / 53 άνδρες, ~645K λέξεις) και τη Ρόδο (35 μαρτυρίες, 30 γυναίκες / 5 άνδρες, ~168K λέξεις).","about.corpus_asr":"Οι ιταλικές μαρτυρίες και οι ελληνικές του USHMM μεταγράφηκαν με Αυτόματη Αναγνώριση Ομιλίας (Whisper Large v3). Οι μαρτυρίες MoG και Istorima έχουν χειρόγραφες μεταγραφές. Εφαρμόζονται ελάχιστα όρια συχνότητας σε όλο το pipeline για τον φιλτράρισμα τεχνητών σφαλμάτων ASR.","about.nlp_title":"Επεξεργασία Φυσικής Γλώσσας","about.nlp_p1":"Οι μαρτυρίες επεξεργάστηκαν με spaCy (<code>el_core_news_lg</code> για ελληνικά, <code>it_core_news_lg</code> για ιταλικά), εξάγοντας λήμματα και μέρη του λόγου σύμφωνα με το Universal Dependencies. Διατηρούνται μόνο ουσιαστικές λέξεις (ουσιαστικά, ρήματα, επίθετα, επιρρήματα, κύρια ονόματα)· λειτουργικές λέξεις και αριθμοί εξαιρούνται.","about.plain_terms":"Με απλά λόγια:","about.nlp_plain":"Η διαδικασία επιχειρεί να ανάγει κάθε λέξη στη λεξικογραφική της μορφή (π.χ. <em>andavamo</em> → <em>andare</em>, <em>ερχόταν</em> → <em>έρχομαι</em>). Η λημματοποίηση στα ιταλικά είναι γενικά αξιόπιστη, αλλά στα ελληνικά είναι λιγότερο ακριβής — ορισμένοι κλιτοί τύποι μπορεί να εμφανίζονται ως ξεχωριστά λήμματα.","about.headword_title":"Επιλογή λημμάτων","about.headword_p1":"Το λεξικό περιέχει περίπου 400 λήμματα που επιλέχθηκαν σε πολλαπλά στάδια. Οι λέξεις πρέπει να εμφανίζονται τουλάχιστον 30 φορές σε τουλάχιστον 3 μαρτυρίες, ελέγχονται για στατιστική διακριτικότητα και ακολουθεί χειροκίνητη επιμέλεια. Επιπλέον, ορισμένες λέξεις προστίθενται χειροκίνητα όταν κρίνονται ενδιαφέρουσες, καθώς η ανάλυση λέξεων-κλειδιών αναδεικνύει <em>διαφορές</em> και όχι κοινά στοιχεία μεταξύ των υποσωμάτων.","about.headword_plain":"Τα περισσότερα λήμματα είναι λέξεις που χρησιμοποιούνται σημαντικά περισσότερο από μία ομάδα επιζώντων. Ένας μικρότερος αριθμός προστίθεται χειροκίνητα γιατί έχουν ιστορική βαρύτητα ακόμα κι αν είναι κοινά σε όλες τις ομάδες.","about.frequency_title":"Συχνότητα & Διασπορά","about.frequency_p1":"Για κάθε λήμμα υπολογίζουμε συχνότητα, εύρος (αριθμός μαρτυριών), συχνότητα ανά εκατομμύριο λέξεις και Απόκλιση Αναλογιών του Gries (DP; Gries 2008). Το DP μετρά πόσο ομοιόμορφα κατανέμεται μια λέξη στις μαρτυρίες (0–1): DP=0 σημαίνει ομοιόμορφη κατανομή, DP κοντά στο 1 σημαίνει συγκέντρωση σε λίγες.","about.frequency_plain":"Μια λέξη όπως <em>guerra</em> (πόλεμος) που εμφανίζεται σχεδόν σε όλες τις ιταλικές μαρτυρίες έχει χαμηλό DP, ενώ μια λέξη όπως <em>cantoni</em> που εμφανίζεται κυρίως στις μαρτυρίες της Ρόδου έχει υψηλό DP.","about.keyword_title":"Ανάλυση λέξεων-κλειδιών","about.keyword_p1":"Οι λέξεις-κλειδιά είναι λέξεις που χρησιμοποιούνται σημαντικά περισσότερο από μία ομάδα επιζώντων. Κατατάσσονται με <strong>λόγο συχνότητας</strong> (×N) — πόσες φορές πιο συχνή είναι μια λέξη σε μια ομάδα σε σχέση με άλλη. Π.χ. ×4,1 σημαίνει περίπου 4 φορές πιο συχνή.","about.keyword_p2":"Εμφανίζονται μόνο λέξεις που περνούν έλεγχο στατιστικής σημαντικότητας, διασφαλίζοντας ότι οι διαφορές είναι πραγματικές και όχι τυχαίες. Απαιτείται ελάχιστη συχνότητα 10 και εμφάνιση σε τουλάχιστον 3 μαρτυρίες.","about.keyword_p3":"Οι συγκρίσεις γίνονται εντός του ίδιου αρχείου: CDEC Ιταλίας γυναίκες vs. άνδρες, USHMM Ελλάδας γυναίκες vs. άνδρες, και CDEC Ιταλία vs. Ρόδος.","about.keyword_plain":"Π.χ. αν η λέξη <em>mamma</em> εμφανίζεται περίπου 4 φορές πιο συχνά στις γυναίκες από τους άνδρες, εμφανίζεται ως ×4,1.","about.gender_analysis_title":"Ανάλυση φύλου","about.gender_analysis_p1":"Η σελίδα σύγκρισης φύλου δείχνει λέξεις καταταγμένες κατά λόγο συχνότητας (×N). Στο παρασκήνιο, οι λέξεις προφιλτράρονται με δύο επιπλέον ελέγχους που πρέπει να συμφωνούν στην κατεύθυνση:","about.gender_analysis_zeta":"<strong>Zeta του Burrows</strong> (Burrows 2007; Schöch 2018) — μετρά σε <em>πόσες μαρτυρίες</em> εμφανίζεται η λέξη σε κάθε πλευρά, αποτρέποντας μια μεμονωμένη μακρά μαρτυρία να καθορίσει το αποτέλεσμα.","about.gender_analysis_g2":"Ένας <strong>έλεγχος στατιστικής σημαντικότητας</strong> που διασφαλίζει ότι η διαφορά δεν οφείλεται σε τύχη. Εμφανίζονται μόνο επιβεβαιωμένες λέξεις.","about.gender_analysis_plain":"Μια λέξη μπαίνει στη λίστα μόνο αν είναι και πιο συχνή και πιο διαδεδομένη στις μαρτυρίες μιας πλευράς.","about.collocation_title":"Ανάλυση συνταγματικών συνάψεων","about.collocation_p1":"Οι συνταγματικές συνάψεις είναι ζεύγη λέξεων που εμφανίζονται μαζί πολύ πιο συχνά από ό,τι θα περιμέναμε τυχαία. Κατατάσσονται με <strong>Mutual Information</strong> (MI; Church &amp; Hanks 1990), που μετρά πόσο ισχυρά «έλκονται» δύο λέξεις μεταξύ τους. Ζεύγη υψηλού MI όπως <em>camera + gas</em>, <em>stella + davide</em>, <em>fame + sete</em> (πείνα + δίψα) αναδεικνύουν το χαρακτηριστικό λεξιλόγιο των μαρτυριών.","about.collocation_p2":"Εμφανίζεται επίσης η συχνότητα συνεμφάνισης. Παράθυρο ±5 λέξεις, ελάχιστο 3 συνεμφανίσεις σε 3 μαρτυρίες.","about.collocation_plain":"","about.sketch_title":"Λεξικογραφικά σκίτσα & Πολυλεκτικές εκφράσεις","about.sketch_p1":"Τα λεξικογραφικά σκίτσα (Kilgarriff et al. 2004, 2014) ομαδοποιούν τις συνεμφανίσεις κατά γραμματική σχέση. Για ένα ουσιαστικό βλέπουμε <em>ποια ρήματα το παίρνουν ως υποκείμενο</em>, <em>ποια επίθετα το προσδιορίζουν</em>, και <em>ποια άλλα ουσιαστικά εμφανίζονται δίπλα του</em>. Ισχύς συσχέτισης με logDice.","about.sketch_p2":"Οι πολυλεκτικές εκφράσεις εξάγονται με δύο μεθόδους: συντακτική ανάλυση εξαρτήσεων και διγράμματα/τριγράμματα φιλτραρισμένα με PMI (PMI ≥ 5.0). Αυτό συλλαμβάνει πάγιες φράσεις όπως <em>campo di concentramento</em>, <em>croce rossa</em>.","about.thesaurus_title":"Κατανομητικός θησαυρός","about.thesaurus_p1":"Ο κατανομητικός θησαυρός κατατάσσει τα λήμματα κατά ομοιότητα χρήσης (Kilgarriff et al. 2004; Rychlý & Kilgarriff 2007). Κάθε λήμμα αναπαρίσταται ως διάνυσμα ζευγών (γραμματική_σχέση, συνάψη) σταθμισμένο με logDice. Ομοιότητα με συνημίτονο.","about.thesaurus_plain":"Δύο λέξεις θεωρούνται όμοιες αν εμφανίζονται στα ίδια είδη προτάσεων με τα ίδια είδη γειτονικών λέξεων. Κάθε βαθμολογία ομοιότητας ανιχνεύεται σε συγκεκριμένες κοινές συνάψεις.","about.emotion_title":"Προφίλ συναισθημάτων","about.emotion_p1":"Κάθε λήμμα λαμβάνει προφίλ συναισθημάτων με το NRC Emotion Lexicon (Mohammad & Turney 2013), που συσχετίζει λέξεις με 8 βασικά συναισθήματα (θυμός, προσδοκία, αηδία, φόβος, χαρά, λύπη, έκπληξη, εμπιστοσύνη). Για κάθε λήμμα, συλλέγουμε όλες τις περιβάλλουσες λέξεις και αναζητούμε τις συναισθηματικές τους συσχετίσεις.","about.emotion_plain":"Αυτό δείχνει ποια συναισθήματα περιβάλλουν μια λέξη όταν τη χρησιμοποιούν οι επιζώντες. Το NRC λεξικό είναι κοινό για ελληνικά και ιταλικά, επιτρέποντας άμεση σύγκριση μεταξύ γλωσσών.","about.narrative_title":"Αφηγηματική θέση","about.narrative_p1":"Κάθε μαρτυρία χωρίζεται σε 10 ίσα τμήματα (δεκατημόρια). Για κάθε λήμμα, μετράμε εμφανίσεις ανά δεκατημόριο και ελέγχουμε με chi-squared goodness-of-fit.","about.narrative_plain":"Αποκαλύπτει <em>πότε</em> στο τόξο της μαρτυρίας χρησιμοποιούνται συγκεκριμένες λέξεις. Λέξεις όπως <em>scuola</em> (σχολείο) κορυφώνονται στο πρώτο δεκατημόριο — οι επιζώντες ξεκινούν με την προπολεμική ζωή. Λέξεις όπως <em>guerra</em> (πόλεμος) κορυφώνονται στο δεύτερο και τρίτο.","about.crosslingual_title":"Διαγλωσσική σύγκριση","about.crosslingual_p1":"Ελληνο-ιταλικά ζεύγη λέξεων επιμελήθηκαν από δίγλωσσα λεξικά. Για κάθε ζεύγος, τα λεξικογραφικά σκίτσα συγκρίνονται: κοινές συνάψεις αναγνωρίζονται με διαγλωσσικά embeddings, ενώ οι μοναδικές αποκαλύπτουν γλωσσο-ειδικές συσχετίσεις.","about.crosslingual_plain":"Για το ζεύγος <em>πόλεμος</em> ↔ <em>guerra</em>, μπορούμε να συγκρίνουμε ποιες λέξεις περιβάλλουν τον «πόλεμο» σε κάθε γλώσσα — αποκαλύπτοντας αν οι δύο κοινότητες πλαισιώνουν την ίδια έννοια με παρόμοιο ή διαφορετικό λεξιλόγιο.","about.gender_dim_title":"Διάσταση φύλου","about.gender_dim_p1":"Κεντρικός στόχος είναι να εξετάσουμε πώς γυναίκες και άνδρες αφηγούνται τις ίδιες εμπειρίες με διαφορετικό λεξιλόγιο. Το ιταλικό CDEC προσφέρει την πιο ισορροπημένη σύγκριση (48 γυναίκες / 53 άνδρες). Το ελληνικό USHMM (13Γ vs 40Α) έχει μικρότερο γυναικείο δείγμα.","about.gender_dim_p2":"Οι στατιστικές φύλου συνδυάζουν μέτρα σε επίπεδο εγγράφου (ελέγχοντας πόσες μαρτυρίες χρησιμοποιούν μια λέξη, όχι μόνο πόσο συχνά) με μέτρα βασισμένα στη συχνότητα, ώστε να αποφεύγεται η διόγκωση αποτελεσμάτων από λίγες μακροσκελείς μαρτυρίες.","about.limitations_title":"Περιορισμοί","about.limit_asr":"<strong>Ποιότητα ASR:</strong> Οι ιταλικές και ελληνικές USHMM μαρτυρίες μεταγράφηκαν αυτόματα. Ορισμένος θόρυβος παραμένει.","about.limit_greek":"<strong>Ελληνική λημματοποίηση:</strong> Η αυτόματη λημματοποίηση για τα ελληνικά είναι λιγότερο ακριβής από την ιταλική, ειδικά για ρηματικούς τύπους προφορικού λόγου. Ορισμένοι κλιτοί τύποι μπορεί να εμφανίζονται ως ξεχωριστά λήμματα αντί να ομαδοποιούνται.","about.limit_small":"","about.limit_imbalance":"","about.references_title":"Αναφορές","about.credits_title":"Συντελεστές","about.credits_p1":"","about.credits_p2":"Οι μαρτυρίες παρέχονται από το CDEC (Centro di Documentazione Ebraica Contemporanea, Μιλάνο), το United States Holocaust Memorial Museum (USHMM), το έργο Μνήμες της Κατοχής στην Ελλάδα (MoG) και το έργο προφορικής ιστορίας Istorima.","common.loading":"Φόρτωση…","common.language":"Γλώσσα","common.greek":"Ελληνικά","common.italian":"Ιταλικά","common.female":"Γυναίκα","common.male":"Άνδρας","common.decile_labels":["Προπολεμική","Αρχές πολέμου","Δίωξη","Εκτόπιση","Στρατόπεδα","Καθημερινότητα","Απελευθέρωση","Επόμενη μέρα","Αναστοχασμός","Κληρονομιά"],"footer.cofunded":"Συγχρηματοδοτείται από την Ευρωπαϊκή Ένωση","footer.partners":"Mubat (συντονιστής) · Fondazione CDEC · Αριστοτέλειο Πανεπιστήμιο Θεσσαλονίκης · UVSQ","footer.ai_translation":"Η ελληνική και η ιταλική έκδοση αυτού του ιστότοπου μεταφράστηκαν με τη βοήθεια τεχνητής νοημοσύνης. Μπορεί να υπάρχουν ανακρίβειες.","footer.disclaimer":"Χρηματοδοτείται από την Ευρωπαϊκή Ένωση. Οι απόψεις και οι γνώμες που εκφράζονται είναι αποκλειστικά του/των συγγραφέα/ων και δεν αντικατοπτρίζουν κατ' ανάγκη τις απόψεις της Ευρωπαϊκής Ένωσης ή του Ευρωπαϊκού Εκτελεστικού Οργανισμού Εκπαίδευσης και Πολιτισμού (EACEA). Ούτε η Ευρωπαϊκή Ένωση ούτε η αρχή χορήγησης μπορούν να θεωρηθούν υπεύθυνες γι' αυτές."},it:{"nav.home":"Home","nav.lexicon":"Esplora il Lessico","nav.gender":"Genere","nav.keyness":"Italia vs Rodi","nav.collocations":"Coppie di Parole","nav.crosslingual":"Tra le Lingue","nav.exhibition":"Presentazione","nav.about":"Info","home.title":"Avalanche Lexicon of WWII Memory","home.subtitle":"Elenco bilingue di parole dalle testimonianze orali della Seconda Guerra Mondiale in greco e italiano.","home.intro":"Basato su 397 testimonianze di sopravvissuti da cinque raccolte di storia orale, il lessico mostra come i sopravvissuti hanno scelto le parole per ricordare la guerra.","home.cta":"Esplora il Lessico","home.section1_label":"02 — Le Raccolte","home.section1_title":"Cinque raccolte di storia orale","home.section1_desc":"Il lessico attinge da testimonianze di cinque raccolte di storia orale tra Grecia e Italia, ciascuna conservando un aspetto diverso della memoria bellica e postbellica.","home.section2_label":"01 — Il Lessico","home.section2_title":"Esplora il lessico","home.section2_desc":"Oltre a ~400 lemmi con linee di concordanza, collocati e dati di frequenza, la piattaforma pubblica liste di parole chiave per genere che mostrano come donne e uomini ricordano gli stessi eventi in modo diverso, confronti tra sottocorpora che rivelano come la geografia e la comunità plasmano il linguaggio della testimonianza, coppie di parole specifiche del contesto bellico e 88 equivalenti greco-italiani confrontati attraverso i loro collocati per evidenziare convergenze e divergenze tra le esperienze dei due paesi.","home.btn_lexicon":"Esplora il Lessico","home.btn_gender":"Donne vs Uomini","home.btn_crosslingual":"Tra le Lingue","home.btn_keyness":"Italia vs Rodi","home.btn_exhibition":"Presentazione","home.btn_gender_desc":"Quali parole usano di più le donne rispetto agli uomini, e viceversa?","home.btn_crosslingual_desc":"88 coppie di parole greco-italiane confrontate attraverso i loro contesti.","home.btn_keyness_desc":"Come cambia il vocabolario testimoniale tra gli archivi?","home.btn_exhibition_desc":"Presentazione a schermo intero con lemmi e citazioni dalle testimonianze.","home.btn_lexicon_desc":"Sfoglia ~400 lemmi con concordanze, schemi lessicali e dati di frequenza.","home.testimonies":"testimonianze","home.women":"donne","home.men":"uomini","home.women_only":"solo donne","gender.title":"Genere","gender.intro":"Parole che donne e uomini usano in modo diverso quando raccontano le stesse storie. Le barre mostrano quanto fortemente ogni parola è associata a un gruppo.","gender.underlined_note":"Le parole sottolineate sono nel lessico — clicca per esplorare. Passa il cursore per i dettagli.","gender.micro_guide":"Le parole sono ordinate per quante volte sono più frequenti in un gruppo. Barra più lunga = differenza maggiore. Clicca su una parola sottolineata per il profilo completo.","gender.more_in_women":"più nelle donne","gender.more_in_men":"più negli uomini","gender.only_women":"solo nelle testimonianze femminili","gender.only_men":"solo nelle testimonianze maschili","gender.hl_ravensbruck":"Ravensbrück era il più grande campo di concentramento nazista principalmente per donne. Appare esclusivamente nelle testimonianze femminili in questo corpus.","gender.hl_gusen":"Gusen era un sottocampo di Mauthausen dove i prigionieri maschi erano sottoposti ai lavori forzati nelle cave di granito. Appare esclusivamente nelle testimonianze maschili.","gender.hl_miniera":"Il lavoro forzato nelle miniere era un'esperienza specifica dei deportati maschi. La parola non appare nelle testimonianze femminili.","gender.hl_mamma":"Oltre 4 volte più frequente nelle testimonianze femminili. Principali collocati: papà, sorella, fratello — la madre è al centro di un lessico familiare.","gender.hl_mama_gr":'La parola per "mamma" è oltre 17 volte più frequente per milione di parole nelle testimonianze femminili rispetto a quelle maschili.',"gender.hl_thimame":"Le donne segnalano esplicitamente l'atto del ricordare più del doppio — una differenza di inquadramento narrativo, non solo di contenuto.","gender.show_exploratory":"Mostra anche parole non confermate","gender.sort_by":"Ordina per:","gender.distinctiveness":"Quanto distintiva","gender.freq_ratio":"Volte più frequente","gender.stat_strength":"Certezza","gender.women_distinctive":"Distintive femminili","gender.men_distinctive":"Distintive maschili","gender.words":"parole","gender.word_present":"parola presente","gender.word_absent":"parola assente","gender.women_testimonies":"Quadrati a sinistra = testimonianze femminili","gender.men_testimonies":"Quadrati a destra = testimonianze maschili","gender.each_square":"Ogni quadrato è una testimonianza. Pieno = la parola vi compare.","gender.col_word":"parola","gender.col_testimonies":"testimonianze","keyness.title":"Italia vs Rodi","keyness.intro":"Quali parole usano di più i sopravvissuti ebrei italiani rispetto alla comunità di Rodi, e viceversa?","keyness.fold_note":"Il valore ×N indica quante volte più comune è una parola da un lato.","keyness.gender_link":"Per confronti di genere, vedi la pagina","keyness.gender_page":"Genere","keyness.micro_guide":"Ogni parola mostrata è usata significativamente di più da un gruppo. Barra più lunga = differenza maggiore.","keyness.metric":"Misura:","keyness.show_top":"Mostra","keyness.per_side":"per lato","keyness.central_axis":"centro","keyness.sig":"confermate","keyness.terms":"parole","colloc.title":"Coppie di Parole","colloc.intro":"Parole che appaiono vicine insolitamente spesso nelle testimonianze. Esplora per archivio e tipo di parola.","colloc.micro_guide":"Seleziona un archivio, clicca sulle intestazioni di colonna per ordinare per MI (coppie più distintive) o frequenza (più comuni). Cerca qualsiasi parola.","colloc.no_data":"Nessuna coppia di parole per questa combinazione.","colloc.legend_mi":"<strong>MI</strong> (Informazione Mutua) — misura quanto fortemente due parole si attraggono. MI più alto = la coppia appare insieme molto più di quanto ci si aspetterebbe per caso.","colloc.legend_freq":"<strong>Freq</strong> — quante volte la coppia appare insieme nelle testimonianze.","colloc.legend_tip":"Clicca sulle intestazioni di colonna per riordinare per MI (coppie più distintive) o per frequenza (coppie più comuni).","cross.title":"Tra le Lingue","cross.intro":"Coppie di parole greco-italiane che significano la stessa cosa. Dove disponibile, ogni coppia mostra quali parole vicine sono condivise e quali appaiono solo in una lingua.","cross.micro_guide":"Ogni scheda confronta una coppia greco-italiana attraverso i collocati. Chip verdi = comuni a entrambe le lingue. Blu = solo greco. Arancione = solo italiano. Clicca su una parola per la voce completa.","cross.pairs_with_data":"coppie con dati","cross.search_placeholder":"Cerca parola o significato...","cross.pairs":"coppie","cross.both":"entrambe:","cross.only_greek":"solo greco:","cross.only_italian":"solo italiano:","lexicon.label":"Esplora il Lessico","lexicon.title":"Sfoglia il lessico completo","lexicon.desc":"Cerca ed esplora tutte le parole. Clicca su qualsiasi scheda per estratti dalle testimonianze, schemi lessicali, frasi comuni e collegamenti con l'altra lingua.","lexicon.micro_guide":"Clicca su una scheda per estratti dalle testimonianze (concordanze), schemi d'uso (word sketches), parole simili e dati di frequenza. Usa la barra di ricerca o filtra per lingua.","lexicon.search_placeholder":"Cerca parole...","lexicon.all":"Tutti","lexicon.greek":"Greco","lexicon.italian":"Italiano","lexicon.entries":"parole","lexicon.loading":"Caricamento...","lexicon.occurrences":"volte","lexicon.files":"testimonianze","lexicon.concordances":"Con le loro parole","lexicon.how_used":"Come si usa questa parola","lexicon.show_less":"Mostra meno","lexicon.show_all_patterns":"Mostra tutti ({n})","lexicon.sketch_footer":"Parole che appaiono negli stessi schemi, ordinate per quanto vanno insieme","lexicon.common_phrases":"Frasi comuni","lexicon.words_similar":"Parole usate in modo simile","lexicon.thes_footer":"Parole usate allo stesso modo con le stesse parole compagne nelle testimonianze.","lexicon.keyness_profile":"Dove questa parola spicca","lexicon.more_frequent":"più frequente","lexicon.less_frequent":"meno frequente","lexicon.crosslingual_links":"Nell'altra lingua","exhibit.occurrences":"volte","exhibit.peaks_decile":"Più comune intorno a","exhibit.shared_collocates":"collocati condivisi","explore.title":"Esplora per Tema","explore.intro":"Il lessico è organizzato in tredici sezioni tematiche che tracciano l'arco della testimonianza — dall'identità e comunità prebellica attraverso la persecuzione, la deportazione e i campi, fino alla resistenza, alla liberazione e al lavoro continuo della memoria.","explore.words":"parole","explore.filter_all":"Tutte le Lingue","explore.filter_greek":"Greco","explore.filter_italian":"Italiano","theme.words_in":"Parole in questo tema","theme.mentions":"menzioni","theme.peak":"Picco","word.testimonies":"Testimonianze","word.distribution":"Distribuzione","word.collocations":"Collocazioni","word.comparisons":"Confronti","word.frequency":"Frequenza","word.archive":"Archivio","word.gender":"Genere","word.filter_all":"Tutti","word.showing":"Visualizzazione di {count} su {total} righe","word.no_kwic":"Nessuna riga di concordanza trovata per questa parola.","word.colloc_title":"Parole che appaiono frequentemente insieme","word.comp_distinctive":"Distintiva in","comp.title":"Confronta Prospettive","comp.intro":"Esplora come diversi gruppi di sopravvissuti hanno usato un vocabolario distintivo per narrare le loro esperienze.","comp.gender_title":"Prospettive Femminili e Maschili","comp.gender_desc":"Come donne e uomini ricordano in modo diverso — il vocabolario distintivo che rivela le esperienze di genere dell'Olocausto.","comp.geo_title":"Rodi e Italia Continentale","comp.geo_desc":"La comunità ebraica di Rodi aveva un'identità unica di lingua ladina. Confronta il linguaggio delle loro testimonianze con quello dei sopravvissuti dell'Italia continentale.","comp.female_keywords":"Parole chiave femminili","comp.male_keywords":"Parole chiave maschili","comp.rhodes_keywords":"Parole chiave di Rodi","comp.italy_keywords":"Parole chiave dell'Italia","corpora.title":"I Corpora","corpora.intro":"Il lessico attinge da testimonianze di storia orale di cinque archivi tra Grecia e Italia, comprendendo 397 testimonianze in due lingue.","corpora.testimonies":"testimonianze","corpora.tokens":"parole","corpora.female":"donne","corpora.male":"uomini","corpora.greek_section":"Archivi Greci","corpora.italian_section":"Archivi Italiani","search.title":"Ricerca Concordanze","search.intro":"Cerca qualsiasi parola nell'intero corpus. I risultati mostrano la parola nel contesto originale della testimonianza.","search.placeholder":"Digita una parola (es. casa, famiglia, guerra)…","search.button":"Cerca","search.indexed":"termini indicizzati","search.no_results":"Nessuna riga di concordanza trovata per","about.title":"Informazioni sul Lessico","about.project_title":"Il progetto AVALANCHE","about.project_p1":"Il Lessico AVALANCHE è sviluppato nell’ambito del Pacchetto di Lavoro 11 del progetto AVALANCHE, finanziato dal programma CERV dell’Unione Europea sulla Memoria Europea (Grant Agreement 101143807).","about.project_p2":"Il progetto si svolge da maggio 2024 ad aprile 2026 e riunisce partner europei — Mubat (coordinatore, Italia), Fondazione CDEC (Italia), Università Aristotele di Salonicco (Grecia) e UVSQ (Francia) — per sviluppare nuovi approcci all’educazione sull’Olocausto attraverso gli archivi di storia orale.","about.publishes_title":"Cosa pubblica il lessico","about.publishes_intro":"Oltre al lessico di circa 400 lemmi, la piattaforma pubblica diverse risorse complementari:","about.publishes_gender":"<strong>Liste di parole chiave per genere</strong> che mostrano quali parole sono distintamente più frequenti nelle testimonianze di donne o uomini — rivelando differenze nel modo in cui sopravvissuti, vittime e testimoni esprimono i loro ricordi.","about.publishes_subcorpus":"<strong>Liste di parole chiave per sottocorpus</strong> che confrontano il vocabolario di comunità diverse — ad esempio, sopravvissuti ebrei in Italia continentale rispetto alla comunità ebraica di Rodi — per evidenziare come la geografia e la comunità plasmano il linguaggio della testimonianza.","about.publishes_collocations":"<strong>Coppie di parole (collocazioni)</strong> che co-occorrono in ogni sottocorpus, classificate per quanto fortemente si attraggono — coppie come <em>camera + gas</em> o <em>fame + sete</em> che rivelano il vocabolario ricorrente della testimonianza.","about.publishes_crosslingual":"<strong>Coppie interlinguistiche</strong>: 88 equivalenti greco-italiani confrontati attraverso i loro collocati, evidenziando dove le esperienze dei due paesi convergono e dove divergono.","about.methodology_title":"Metodologia","about.methodology_note_label":"Nota:","about.methodology_note":"Questo lessico è uno strumento esplorativo di linguistica dei corpora. Evidenzia pattern distribuzionali — quanto spesso appaiono le parole, dove si concentrano e con cosa co-occorrono — come evidenze da interpretare per ricercatori, visitatori di mostre ed educatori. Non formula affermazioni storiche.","about.corpus_title":"Corpus","about.corpus_p1":"Il lessico attinge da 397 testimonianze di storia orale (~2,73 milioni di parole) in due lingue: 261 in greco (~1,92M parole) e 136 in italiano (~0,81M parole).","about.corpus_greek":"Il <strong>corpus greco</strong> comprende testimonianze da tre archivi: USHMM (53 testimonianze, 13 donne / 40 uomini, ~392K parole), Memorie dell’Occupazione in Grecia — MoG (27 testimonianze, tutte donne, ~355K parole), e Istorima (181 testimonianze, tutte donne, ~1,17M parole).","about.corpus_italian":"Il <strong>corpus italiano</strong> consiste in testimonianze CDEC dall’Italia (101 testimonianze, 48 donne / 53 uomini, ~645K parole) e da Rodi (35 testimonianze, 30 donne / 5 uomini, ~168K parole).","about.corpus_asr":"Le testimonianze italiane e quelle greche USHMM sono state trascritte con Riconoscimento Automatico del Parlato (Whisper Large v3). MoG e Istorima hanno trascrizioni manuali. Soglie minime di frequenza vengono applicate per filtrare gli artefatti ASR.","about.nlp_title":"Elaborazione del Linguaggio Naturale","about.nlp_p1":"Le testimonianze sono state elaborate con spaCy (<code>el_core_news_lg</code> per il greco, <code>it_core_news_lg</code> per l’italiano), estraendo lemmi e parti del discorso secondo Universal Dependencies. Solo parole di contenuto (sostantivi, verbi, aggettivi, avverbi, nomi propri) sono mantenute; parole funzionali e numeri sono esclusi.","about.plain_terms":"In parole semplici:","about.nlp_plain":"Il sistema cerca di ricondurre ogni parola alla forma del dizionario (es. <em>andavamo</em> → <em>andare</em>, <em>ερχόταν</em> → <em>έρχομαι</em>). La lemmatizzazione italiana è generalmente affidabile, ma quella greca è meno accurata — alcune forme flesse possono apparire come voci separate.","about.headword_title":"Selezione dei lemmi","about.headword_p1":"Il lessico contiene circa 400 lemmi selezionati in più fasi. Le parole devono apparire almeno 30 volte in almeno 3 testimonianze e sono testate con un test di distintività statistica, seguite da curatela manuale. Alcune parole sono aggiunte manualmente quando ritenute significative, poiché l’analisi delle parole chiave evidenzia le <em>differenze</em> tra sottocorpora, non i tratti comuni.","about.headword_plain":"La maggior parte dei lemmi è usata in modo notevolmente più frequente da un gruppo; un numero minore è aggiunto manualmente per il suo peso storico.","about.frequency_title":"Frequenza e dispersione","about.frequency_p1":"Per ogni lemma calcoliamo frequenza grezza, range (numero di testimonianze), frequenza per milione di parole e Deviazione delle Proporzioni di Gries (DP; Gries 2008). Il DP misura quanto uniformemente una parola si distribuisce nelle testimonianze (0–1): DP=0 significa distribuzione uniforme, DP vicino a 1 significa concentrazione in poche.","about.frequency_plain":"Una parola come <em>guerra</em> che appare in quasi tutte le testimonianze italiane ha DP basso, mentre una come <em>cantoni</em> che appare soprattutto nelle testimonianze di Rodi ha DP alto.","about.keyword_title":"Analisi delle parole chiave","about.keyword_p1":"Le parole chiave sono classificate per <strong>rapporto di frequenza</strong> (×N) — quante volte più frequente è una parola in un gruppo rispetto a un altro (es. ×4,1 = circa quattro volte più frequente).","about.keyword_p2":"Vengono mostrate solo le parole che superano un test di significatività statistica, garantendo che le differenze siano reali. Frequenza minima di 10 e range di almeno 3 testimonianze.","about.keyword_p3":"I confronti avvengono all’interno dello stesso archivio: CDEC Italia donne vs. uomini, USHMM Grecia donne vs. uomini, e CDEC Italia vs. Rodi.","about.keyword_plain":"Se <em>mamma</em> appare circa 4 volte di più nelle testimonianze delle donne rispetto a quelle degli uomini, viene mostrata come ×4,1.","about.gender_analysis_title":"Analisi di genere","about.gender_analysis_p1":"La pagina di confronto di genere mostra parole classificate per rapporto di frequenza (×N). Le parole sono pre-filtrate con due test aggiuntivi che devono concordare nella direzione:","about.gender_analysis_zeta":"<strong>Zeta di Burrows</strong> (Burrows 2007; Schöch 2018) — misura a livello di documento che verifica <em>in quante testimonianze</em> appare una parola per parte, impedendo che una singola testimonianza lunga determini il risultato.","about.gender_analysis_g2":"<strong>Un test di significatività statistica</strong> per assicurare che la differenza non sia dovuta al caso. Solo le parole confermate sono mostrate per default.","about.gender_analysis_plain":"Una parola entra nella lista solo se è sia più frequente sia più diffusa nelle testimonianze di un lato.","about.collocation_title":"Analisi delle collocazioni","about.collocation_p1":"Le collocazioni sono classificate per <strong>Mutual Information</strong> (MI; Church & Hanks 1990) — misura quanto fortemente due parole si attraggono. Coppie ad alto MI come <em>camera + gas</em>, <em>stella + davide</em>, <em>fame + sete</em> emergono perché sono quasi esclusive del contesto testimoniale.","about.collocation_p2":"La tabella mostra la frequenza grezza di co-occorrenza. Finestra di ±5 parole, minimo 3 co-occorrenze in 3 testimonianze.","about.collocation_plain":"","about.sketch_title":"Profili lessicali ed espressioni polirematiche","about.sketch_p1":"I profili lessicali (Kilgarriff et al. 2004, 2014) raggruppano le co-occorrenze per relazione grammaticale. Per un sostantivo vediamo <em>quali verbi lo prendono come soggetto</em>, <em>quali aggettivi lo modificano</em>, e <em>quali altri sostantivi appaiono accanto</em>. Forza di associazione con logDice.","about.sketch_p2":"Le espressioni polirematiche sono estratte con due metodi: analisi sintattica delle dipendenze e bigrammi/trigrammi filtrati con PMI (PMI ≥ 5.0). Questo cattura frasi fisse come <em>campo di concentramento</em>, <em>croce rossa</em>.","about.thesaurus_title":"Thesaurus distribuzionale","about.thesaurus_p1":"Il thesaurus distribuzionale classifica i lemmi per similarità d’uso (Kilgarriff et al. 2004; Rychlý & Kilgarriff 2007). Ogni lemma è un vettore di coppie (relazione_grammaticale, collocato) pesato con logDice. Similarità con coseno.","about.thesaurus_plain":"Due parole sono considerate simili se appaiono negli stessi tipi di frasi con gli stessi tipi di parole vicine. Ogni punteggio di similarità è tracciabile a specifici collocati condivisi.","about.crosslingual_title":"Confronto interlinguistico","about.crosslingual_p1":"Le coppie greco-italiane sono curate da dizionari bilingui e competenza di dominio. Per ogni coppia, i word sketch di entrambe le lingue vengono confrontati: i collocati condivisi (parole usate in modo simile in entrambe le lingue) sono identificati con embeddings interlinguistici, mentre quelli unici rivelano associazioni specifiche della lingua.","about.crosslingual_plain":"Per la coppia <em>πόλεμος</em> (guerra, greco) ↔ <em>guerra</em> (guerra, italiano), possiamo confrontare quali parole circondano «guerra» in ciascuna lingua — rivelando se le due comunità inquadrano lo stesso concetto con un vocabolario simile o diverso.","about.gender_dim_title":"Dimensione di genere","about.gender_dim_p1":"Obiettivo centrale è esaminare come donne e uomini narrano le stesse esperienze con vocabolari diversi. Il corpus CDEC italiano offre il confronto più equilibrato (48 donne / 53 uomini). Il confronto USHMM greco (13D vs 40U) ha un campione femminile più piccolo.","about.gender_dim_p2":"Le statistiche di genere combinano misure a livello di documento (verificando quante testimonianze usano una parola, non solo la frequenza) con misure basate sulla frequenza, per evitare di gonfiare i risultati da poche testimonianze lunghe.","about.limitations_title":"Limitazioni","about.limit_asr":"<strong>Qualità ASR:</strong> Le testimonianze italiane e greche USHMM sono state trascritte automaticamente. Un certo rumore rimane.","about.limit_greek":"<strong>Lemmatizzazione greca:</strong> La lemmatizzazione automatica per il greco è meno accurata rispetto all’italiano, specialmente per le forme verbali del parlato orale. Alcune forme flesse possono comparire come voci separate anziché essere raggruppate sotto un unico lemma.","about.limit_small":"","about.limit_imbalance":"","about.references_title":"Riferimenti","about.credits_title":"Crediti","about.credits_p1":"","about.credits_p2":"Le testimonianze sono fornite da CDEC (Centro di Documentazione Ebraica Contemporanea, Milano), lo United States Holocaust Memorial Museum (USHMM), il progetto Memorie dell’Occupazione in Grecia (MoG) e il progetto di storia orale Istorima.","common.loading":"Caricamento…","common.language":"Lingua","common.greek":"Greco","common.italian":"Italiano","common.female":"Donna","common.male":"Uomo","common.decile_labels":["Pre-guerra","Inizio guerra","Persecuzione","Deportazione","Campi","Vita quotidiana","Liberazione","Dopoguerra","Riflessione","Eredità"],"footer.cofunded":"Cofinanziato dall'Unione Europea","footer.partners":"Mubat (coordinatore) · Fondazione CDEC · Aristotle University of Thessaloniki · UVSQ","footer.ai_translation":"Le versioni greca e italiana di questo sito sono state tradotte con l'assistenza dell'intelligenza artificiale. Potrebbero essere presenti alcune imprecisioni.","footer.disclaimer":"Finanziato dall'Unione Europea. Le opinioni espresse appartengono tuttavia al solo/i autore/i e non riflettono necessariamente le opinioni dell'Unione Europea o dell'Agenzia esecutiva europea per l'istruzione e la cultura (EACEA). Né l'Unione Europea né l'autorità erogatrice possono esserne ritenute responsabili."}};function t(e,c="en"){var b,u;return((b=a[c])==null?void 0:b[e])||((u=a.en)==null?void 0:u[e])||e}function d(e,c="en",b={}){let u=t(e,c);for(const[o,i]of Object.entries(b))u=u.replace(`{${o}}`,i);return u}export{d as a,s as c,l,t};
